// Multi-language i18n for NyayaLens
// Covers all 22 scheduled languages of India + English (23 total)

export type Lang =
  | "en"
  | "hi" // Hindi
  | "bn" // Bengali
  | "te" // Telugu
  | "mr" // Marathi
  | "ta" // Tamil
  | "ur" // Urdu
  | "gu" // Gujarati
  | "kn" // Kannada
  | "ml" // Malayalam
  | "or" // Odia
  | "pa" // Punjabi
  | "as" // Assamese
  | "mai" // Maithili
  | "sa" // Sanskrit
  | "ne" // Nepali
  | "kok" // Konkani
  | "sd" // Sindhi
  | "doi" // Dogri
  | "mni" // Manipuri (Meitei)
  | "brx" // Bodo
  | "sat" // Santali
  | "ks"; // Kashmiri

export interface LanguageMeta {
  code: Lang;
  name: string; // English name
  nativeName: string; // Native script name
}

